"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[1565],{41702:e=>{e.exports=JSON.parse('{"functions":[{"name":"AdjustedThreshold","desc":"The emptiness threshold actually applied, after server fullness.\\n\\nExposed because it is the one piece of arithmetic here worth asserting\\ndirectly, and because its direction is easy to get backwards.\\n\\nWith an explicit `EmptinessModifier` the threshold is simply scaled. Without\\none it runs the original\'s curve, where `server_modifier` is 1 on an EMPTY\\nserver and falls toward 0.5 as it fills. The curve turns that into a LOWER\\neffective threshold, so a busy server spawns MORE -- and past a point it goes\\nnegative, meaning the emptiness check can never fire at all.\\n\\nPreserved as it was. Whether that is the intended behaviour is a question for\\nwhoever owns the loot economy, but it is not a porting decision.","params":[{"name":"threshold","desc":"","lua_type":"number"},{"name":"emptiness_modifier","desc":"","lua_type":"number?"},{"name":"server_modifier","desc":"","lua_type":"number?\\n"}],"returns":[{"desc":"","lua_type":"number\\n"}],"function_type":"method","source":{"line":183,"path":"src2/shared/EmberSharedLibrary/GameShared/Spawning/ItemSpawnData.luau"}},{"name":"Roll","desc":"Roll a spawner into a flat-ish list of ItemSets.\\n\\n`ItemReference` spawners nest: they produce one parent whose `Children` hold\\neverything the rest of the roll generated, which is how a crate spawns with\\nthings already inside it.","params":[{"name":"spawn_data","desc":"","lua_type":"SpawnData"},{"name":"options","desc":"","lua_type":"RollOptions?"}],"returns":[{"desc":"","lua_type":"{ ItemSet }\\n"}],"function_type":"method","source":{"line":282,"path":"src2/shared/EmberSharedLibrary/GameShared/Spawning/ItemSpawnData.luau"}},{"name":"HasAnyItems","desc":"Whether this spawner would produce anything, without rolling its contents.\\n\\nUsed to decide whether a container is worth spawning at all. Consumes the\\nsame random draws `Roll` would for its emptiness checks, so passing a fresh\\n`Random` with the same seed to each gives consistent answers.","params":[{"name":"spawn_data","desc":"","lua_type":"SpawnData"},{"name":"options","desc":"","lua_type":"RollOptions?"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"method","source":{"line":430,"path":"src2/shared/EmberSharedLibrary/GameShared/Spawning/ItemSpawnData.luau"}},{"name":"ServerModifierFor","desc":"Server fullness as an emptiness multiplier: 1 on an empty server, falling to\\n`full_modifier` when it is full.","params":[{"name":"player_count","desc":"","lua_type":"number"},{"name":"max_players","desc":"","lua_type":"number"},{"name":"full_modifier","desc":"","lua_type":"number?\\n"}],"returns":[{"desc":"","lua_type":"number\\n"}],"function_type":"method","source":{"line":458,"path":"src2/shared/EmberSharedLibrary/GameShared/Spawning/ItemSpawnData.luau"}},{"name":"Flatten","desc":"Flatten a rolled tree, innermost first.","params":[{"name":"items","desc":"","lua_type":"{ ItemSet }"}],"returns":[{"desc":"","lua_type":"{ ItemSet }\\n"}],"function_type":"method","source":{"line":479,"path":"src2/shared/EmberSharedLibrary/GameShared/Spawning/ItemSpawnData.luau"}}],"properties":[],"types":[],"name":"ItemSpawnData","desc":"Loot tables: what a spawner rolls, before anything is created.\\n\\nWHAT CHANGED\\n\\n`ItemSpawnDataService` mixed three jobs -- parsing Folder trees into spawn\\ndata, rolling that data into a result, and constructing item objects from\\nthe result. The middle one is the interesting one and the only one with real\\nlogic in it, so it lives here on its own.\\n\\nIt is now pure. Every function takes its `SpawnData` and its `Random` and\\nreturns a plain `ItemSet` tree; nothing is looked up, nothing yields, nothing\\nis constructed. The original opened every public method with\\n`wait_service_ready()`, which yielded until a Folder scan had finished --\\nso a loot roll could not be evaluated at all outside a booted place.\\n\\n`ItemSet` was already the right intermediate. It names a class and a\\nquantity and owns no identity, which is exactly an `ItemStack` minus the\\nconfig lookup; `ItemSpawnService` does that half.\\n\\nEMPTINESS\\n\\nA spawner rolls empty more often on a busy server. That modifier was module\\nstate, recomputed from a player count and a Lighting attribute, and read\\nimplicitly by every call. It is a parameter here -- `Options.ServerModifier`\\n-- which is what makes the threshold arithmetic testable at all.","source":{"line":32,"path":"src2/shared/EmberSharedLibrary/GameShared/Spawning/ItemSpawnData.luau"}}')}}]);